export function premiumCategoryArtwork({
  slug,
  name,
}: {
  slug?: string | null;
  name?: string | null;
}): string {
  const resolved =
    slug || (name ? premiumCategoryNameToSlug[name.trim().toLowerCase()] : undefined);
  return resolved
    ? `/icons/category-library/${resolved}.webp`
    : '/icons/categories/business-premium.webp';
}

const discoveryAliases: Readonly<Record<string, string>> = {
  shopping: 'marketplace',
  events: 'happening-nearby',
  news: 'local-now',
  alerts: 'emergency',
};

export function premiumDiscoveryArtwork(area: string): string {
  const slug = discoveryAliases[area] ?? area;
  return `/icons/discovery/${slug}.webp`;
}
